import {esc,icon} from '/assets/render.js';
import {validateContent} from '/assets/schema.js';
const root=document.querySelector('#admin-root'),key='mostpomocy-cms-draft-v2';let data,sha,session,dirty=false,view='dashboard',selected=0,saving=false,demo=new URLSearchParams(location.search).get('demo')==='1',previewWindow;let toastTimer;
const asset=s=>/^(https:|data:)/.test(s)?esc(s):'/'+esc(s);
const labels={dashboard:'Dashboard',home:'Strona główna',posts:'Wpisy blogowe',categories:'Kategorie',listings:'Ogłoszenia',pages:'Podstrony',navigation:'Menu i stopka',media:'Zdjęcia i pliki',team:'Redakcja',stats:'Statystyki',history:'Historia zmian',settings:'Ustawienia'};
const icons={dashboard:'home',home:'grid',posts:'book',categories:'grid',listings:'file',pages:'file',navigation:'menu',media:'image',team:'people',stats:'chart',history:'file',settings:'settings'};
const toast=(s,error=false)=>{const t=document.querySelector('#toast');t.textContent=s;t.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',error?10000:6500)};
async function api(path,options={}){const res=await fetch('/api/'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CMS-Request':'1',...options.headers}});let d;try{d=await res.json()}catch{throw Error('Sesja wygasła lub serwer nie zwrócił danych. Zaloguj się ponownie.')}if(!res.ok)throw Error([d.error,...(d.details||[])].join('\n'));return d}
function cacheDraft(){try{localStorage.setItem(key,JSON.stringify({data,sha,date:new Date().toISOString(),demo,repo:session?.repo||'demo',branch:session?.branch||'demo'}))}catch{toast('Brak miejsca na kopię lokalną. Wyeksportuj kopię zapasową.',true)}}
function changed(){dirty=true;cacheDraft();updateSavebar()}
function updateSavebar(){const b=document.querySelector('#savebar');if(!b)return;b.classList.toggle('dirty',dirty);document.querySelector('#save-state').textContent=saving?'Zapisywanie…':dirty?'Masz nieopublikowane zmiany. Kopia robocza jest w tej przeglądarce.':demo?'Podgląd demonstracyjny. Dane są zapisane tylko w tej przeglądarce.':'Treść pobrana z GitHuba. Brak niezapisanych zmian.';const btn=document.querySelector('#publish');btn.disabled=saving||!dirty;btn.textContent=saving?'Zapisywanie…':demo?'Zapisz w podglądzie':'Zapisz i opublikuj'}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mostpomocy-kopia-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function save(){if(saving)return;const errors=validateContent(data);if(errors.length){toast(errors.join('\n'),true);return}saving=true;updateSavebar();try{if(demo){dirty=false;cacheDraft();toast('Zapisano lokalnie w podglądzie. Nic nie zmieniono w GitHubie.')}else{const r=await api('content',{method:'PUT',body:JSON.stringify({content:data,sha})});sha=r.sha;dirty=false;localStorage.removeItem(key);toast(r.message)} }catch(e){toast(e.message,true)}finally{saving=false;updateSavebar()}}
function preview(){previewWindow=window.open('/?preview=1','mostpomocy-preview');if(!previewWindow)toast('Przeglądarka zablokowała okno podglądu. Zezwól na jego otwarcie.',true)}
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===previewWindow&&e.data?.type==='mostpomocy-preview-ready')previewWindow.postMessage({type:'mostpomocy-preview',content:data},location.origin)});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
const field=(label,k,value,type='text',hint='')=>`<label>${esc(label)}${type==='textarea'?`<textarea name="${k}" ${k==='body'?'class="body-field"':''} rows="${k==='body'?13:4}">${esc(value)}</textarea>`:`<input type="${type}" name="${k}" value="${esc(value)}" ${type==='color'?'':'autocomplete="off"'}>`}${hint?`<small>${esc(hint)}</small>`:''}</label>`;
const select=(label,k,value,items)=>`<label>${esc(label)}<select name="${k}">${items.map(x=>{const v=typeof x==='string'?x:x.id,l=typeof x==='string'?x:x.title;return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
const navItems=()=>Object.keys(labels).map(k=>`<button data-view="${k}" class="${view===k?'active':''}">${icon(icons[k])}${labels[k]}</button>`).join('');
function shell(){root.innerHTML=`${demo?'<div class="demo-banner">PODGLĄD DASHBOARDU · Możesz edytować treść i otworzyć podgląd. Zmiany pozostają w tej przeglądarce.</div>':''}<header class="admin-top"><button class="admin-menu-toggle" aria-label="Otwórz menu" aria-expanded="false">${icon('menu')}</button><a class="brand" href="/"><img src="/assets/logo.svg" alt=""><span><strong>${esc(data.settings.name)}</strong><small>${esc(data.settings.tagline)}</small></span></a><span class="top-label">Dashboard</span><div class="account"><span class="avatar">${esc(session.email.slice(0,1).toUpperCase())}</span><span>${esc(session.email)}</span>${demo?'<a href="/admin/">Logowanie →</a>':'<a href="/cdn-cgi/access/logout">Wyloguj →</a>'}</div></header><div class="admin-layout"><aside class="sidebar"><div class="sidebar-label">TWOJA WITRYNA</div>${navItems()}<div class="sidebar-bottom"><a href="${esc(data.settings.siteUrl)}" target="_blank" rel="noopener">${icon('globe')}Otwórz witrynę ↗</a><a href="https://github.com/${esc(session.repo||'mostpomocy/mostpomocy.github.io')}" target="_blank" rel="noopener">${icon('file')}Repozytorium GitHub ↗</a></div></aside><main class="admin-main"><div class="admin-heading"><div><h1>${view==='dashboard'?'Witaj ponownie! 👋':labels[view]}</h1><p>${view==='dashboard'?'Oto podsumowanie Twojej witryny.':'Zarządzaj treścią MostPomocy w jednym miejscu.'}</p></div><div class="heading-actions"><button class="btn outline" id="preview">${icon('globe')} Podgląd zmian</button><button class="btn outline" id="backup">Eksport kopii</button></div></div><div class="savebar" id="savebar"><span id="save-state"></span><div><button class="btn outline" id="reload">Pobierz ponownie</button><button class="btn" id="publish">Zapisz i opublikuj</button></div></div><section id="view-content"></section></main></div>`;
 root.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;selected=0;shell()});document.querySelector('.admin-menu-toggle').onclick=e=>{const open=document.querySelector('.sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))};document.querySelector('#preview').onclick=preview;document.querySelector('#backup').onclick=exportData;document.querySelector('#publish').onclick=save;document.querySelector('#reload').onclick=async()=>{if(dirty&&!confirm('Pobrać ponownie i odrzucić niezapisane zmiany? Możesz wcześniej wyeksportować kopię.'))return;try{if(demo)data=await fetch('/content/public.json').then(r=>r.json());else{const r=await api('content');data=r.content;sha=r.sha}dirty=false;localStorage.removeItem(key);shell();toast('Pobrano treść ponownie')}catch(e){toast(e.message,true)}};updateSavebar();drawView()}
function dashboard(){const pub=data.posts.filter(x=>x.status==='published').length,drafts=data.posts.length-pub+data.listings.filter(x=>x.status==='draft').length;const stats=[['Wpisy blogowe',data.posts.length,'Wszystkie wpisy w treści'],['Ogłoszenia',data.listings.length,'Wszystkie ogłoszenia'],['Kategorie',data.categories.length,'Obszary pomocy'],['Szkice',drafts,'Materiały do dopracowania']];return `<div class="stats-grid">${stats.map(([l,v,sub])=>`<div class="stat"><label>${l}</label><strong>${v}</strong><small>${sub}</small></div>`).join('')}</div><div class="dashboard-grid"><div class="panel"><h2>Stan redakcji</h2><p>Opublikowane wpisy: ${pub} z ${data.posts.length}. Poniżej rzeczywiste dane zapisane w treści witryny.</p><div class="progress-track"><div style="width:${data.posts.length?pub/data.posts.length*100:0}%"></div></div><h2>Ostatnie wpisy</h2>${data.posts.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(p=>`<div class="recent-item"><img src="${asset(p.image||data.settings.heroImage)}" alt=""><div><h3>${esc(p.title)}</h3><small>${esc(p.date)} · ${p.status==='published'?'Opublikowany':'Szkic'}</small></div><button data-edit-post="${esc(p.id)}">Edytuj</button></div>`).join('')||'<p>Dodaj pierwszy artykuł.</p>'}</div><div><div class="panel"><h2>Szybkie akcje</h2><div class="quick-actions"><button class="btn" data-new="posts">${icon('plus')} Dodaj wpis blogowy</button><button class="btn" data-new="listings">${icon('plus')} Dodaj ogłoszenie</button><button class="btn outline" data-go="categories">${icon('grid')} Zarządzaj kategoriami</button><button class="btn outline" data-go="settings">${icon('settings')} Ustawienia strony</button></div></div><div class="panel" style="margin-top:20px"><h2>Szybki podgląd</h2><div class="mini-preview"><img src="${asset(data.settings.heroImage)}" alt=""><strong>${esc(data.settings.name)}</strong><p>${esc(data.settings.tagline)}</p></div></div></div></div>`}
function bindGo(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view=b.dataset.go;selected=0;shell()});document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>{view=b.dataset.new;addItem()});document.querySelectorAll('[data-edit-post]').forEach(b=>b.onclick=()=>{view='posts';selected=data.posts.findIndex(p=>p.id===b.dataset.editPost);shell()})}
function bindForm(target,transforms={}){const form=document.querySelector('#editor-form');form?.addEventListener('input',e=>{const name=e.target.name;if(!name)return;const previous=target[name];target[name]=transforms[name]?transforms[name](e.target.value):e.target.value;if(name==='id'&&templates[view]){if(view==='categories')for(const item of [...data.posts,...data.listings])if(item.category===previous)item.category=target.id;const prefix={pages:'/',posts:'/blog/',categories:'/kategorie/',listings:'/ogloszenia/'}[view];for(const item of [...data.navigation,...data.footerLinks,...data.categories.flatMap(c=>c.links)])if(item.href===prefix+previous+'/')item.href=prefix+target.id+'/'}changed()});form?.addEventListener('submit',e=>e.preventDefault())}
function homeEditor(){const h=data.home;const names={eyebrow:'Mały nagłówek',title:'Tytuł główny',subtitle:'Podtytuł',description:'Opis w nagłówku',handwritten:'Odręczny dopisek',primaryLabel:'Przycisk: znajdź pomoc',secondaryLabel:'Przycisk: dodaj ogłoszenie',categoriesTitle:'Nagłówek kategorii',categoriesDescription:'Opis kategorii',postsTitle:'Nagłówek blogu',postsDescription:'Opis blogu',ctaTitle:'Nagłówek dolnego banera',ctaDescription:'Opis dolnego banera',ctaLabel:'Tekst przycisku banera'};return `<div class="editor-help">Każdy tekst strony głównej edytujesz tutaj. Zdjęcie nagłówka i logo zmienisz w Ustawieniach, a kolory i układ kategorii w zakładce Kategorie.</div><div class="panel"><form class="editor-form" id="editor-form">${Object.entries(names).map(([k,l])=>field(l,k,h[k],['description','ctaDescription'].includes(k)?'textarea':'text')).join('')}</form></div>`}
function settingsEditor(){const s=data.settings;return `<div class="editor-help">Adres panelu powinien prowadzić do domeny chronionej Cloudflare Access, np. https://admin.mostpomocy.pl. Nie wpisuj tutaj haseł ani tokenów — przechowuje je Cloudflare.</div><div class="panel"><form id="editor-form" class="editor-form"><div class="field-columns">${field('Nazwa witryny','name',s.name)}${field('Hasło marki','tagline',s.tagline)}</div>${field('Opis witryny (SEO)','description',s.description,'textarea')}<div class="field-columns">${field('Publiczny adres strony','siteUrl',s.siteUrl,'url')}${field('Adres panelu Cloudflare','adminUrl',s.adminUrl,'url')}${field('Kontakt e-mail','email',s.email,'email')}${field('Kolor główny','primaryColor',s.primaryColor,'color')}</div>${field('Logo: adres pliku','logo',s.logo,'text','Np. assets/logo.svg. Zdjęcia możesz dodać w zakładce Zdjęcia i pliki.')}${field('Zdjęcie nagłówka: adres pliku','heroImage',s.heroImage)}${field('Tekst stopki','footerText',s.footerText)}${field('Województwa / regiony','regionOptions',s.regionOptions.join('\n'),'textarea','Jeden region w każdym wierszu. Zachowaj „Cała Polska” jako pierwszą pozycję.')}${field('Adres zewnętrznych statystyk','analyticsUrl',s.analyticsUrl,'url','Opcjonalnie link do Twojego dashboardu analitycznego.')}</form><hr style="border:0;border-top:1px solid #28435a;margin:30px 0"><h2>Przywróć kopię zapasową</h2><p>Import zastąpi bieżącą wersję roboczą. Opublikowanie nadal wymaga kliknięcia przycisku zapisu.</p><input type="file" id="import-content" accept="application/json"></div>`}
const templates={categories:()=>({id:'nowa-kategoria-'+Date.now().toString(36),title:'Nowa kategoria',description:'Krótki opis pomocy',icon:'heart',color:'#087dff',body:'Opis kategorii.',links:[]}),posts:()=>({id:'nowy-wpis-'+Date.now().toString(36),title:'Nowy wpis',excerpt:'Krótki opis artykułu.',category:data.categories[0]?.id||'',region:'Cała Polska',date:new Date().toISOString().slice(0,10),image:data.settings.heroImage,status:'draft',body:'## Nowy artykuł\n\nTutaj wpisz treść.'}),listings:()=>({id:'nowe-ogloszenie-'+Date.now().toString(36),title:'Nowe ogłoszenie',excerpt:'Krótki opis ogłoszenia.',category:data.categories[0]?.id||'',region:'Cała Polska',date:new Date().toISOString().slice(0,10),image:'',status:'draft',body:'Opis ogłoszenia.',type:'Oferuję pomoc',contact:''}),pages:()=>({id:'nowa-strona-'+Date.now().toString(36),title:'Nowa podstrona',body:'## Nagłówek\n\nTreść podstrony.'})};
function addItem(){if(!templates[view])return;data[view].push(templates[view]());selected=data[view].length-1;changed();shell()}
function collectionEditor(){const items=data[view],o=items[selected];return `<div class="editor-help">Zmiany zapisują się w kopii roboczej. Publikację uruchamia „Zapisz i opublikuj”. W treści możesz stosować nagłówki „##”, listy „- ” i pogrubienie „**tekst**”. Szkice nie pojawiają się na stronie, ale są widoczne w publicznym repozytorium GitHub.</div><div class="edit-layout"><aside class="item-list"><div class="list-toolbar"><button class="btn" id="add-item">${icon('plus')} Dodaj nowy element</button></div>${items.map((x,i)=>`<button class="${selected===i?'active':''}" data-select="${i}">${esc(x.title)}<small>${x.status?x.status==='draft'?'Szkic':'Opublikowany':esc(x.id)}</small></button>`).join('')}</aside><div class="panel">${o?`<div class="form-heading"><h2>Edycja elementu</h2><div><button class="btn outline" id="move-up" ${selected===0?'disabled':''}>↑</button> <button class="btn outline" id="move-down" ${selected===items.length-1?'disabled':''}>↓</button></div></div><form id="editor-form" class="editor-form" style="margin-top:20px">${field('Tytuł','title',o.title)}${field('Identyfikator w adresie URL','id',o.id,'text','Małe litery bez polskich znaków, cyfry i myślniki. Zmiana adresu może unieważnić stare odnośniki.')}${view==='categories'?`${field('Krótki opis','description',o.description)}<div class="field-columns">${select('Ikona','icon',o.icon,['accessibility','heart','people','home','briefcase','coins','leaf','hands','pin','globe'])}${field('Kolor kategorii','color',o.color,'color')}</div>`:''}${['posts','listings'].includes(view)?`${field('Zajawka / krótki opis','excerpt',o.excerpt,'textarea')}<div class="field-columns">${select('Kategoria','category',o.category,data.categories)}${select('Status','status',o.status,[{id:'draft',title:'Szkic'},{id:'published',title:'Opublikowany'}])}${select('Województwo','region',o.region,data.settings.regionOptions)}${field('Data','date',o.date,'date')}</div>${field('Zdjęcie: adres pliku','image',o.image,'text','Wklej ścieżkę ze Zdjęć i plików, np. assets/uploads/zdjecie.jpg.')}`:''}${view==='listings'?`${select('Rodzaj ogłoszenia','type',o.type,['Oferuję pomoc','Szukam pomocy','Wydarzenie'])}${field('Publiczny kontakt','contact',o.contact)}`:''}${field('Treść','body',o.body,'textarea')}${view==='categories'?field('Przydatne odnośniki','links',o.links.map(l=>l.label+' | '+l.href).join('\n'),'textarea','Jeden odnośnik w wierszu: Nazwa | https://adres.pl'):''}<button type="button" class="btn danger" id="delete-item">Usuń element</button></form>`:'<div class="blank-state"><h2>Brak elementów</h2><p>Dodaj pierwszy element przyciskiem obok.</p></div>'}</div></div>`}
function bindCollection(){document.querySelector('#add-item').onclick=addItem;document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.select);drawView()});const o=data[view][selected];if(!o)return;bindForm(o,{links:v=>v.split('\n').filter(l=>l.trim()).map(l=>{const i=l.indexOf('|');return {label:(i<0?l:l.slice(0,i)).trim(),href:(i<0?'':l.slice(i+1)).trim()}})});document.querySelector('#delete-item').onclick=()=>{if(view==='categories'&&[...data.posts,...data.listings].some(x=>x.category===o.id)){toast('Najpierw przypisz wpisy i ogłoszenia do innej kategorii.',true);return}if(view==='pages'&&o.id==='kontakt'){toast('Strona Kontakt jest wymagana.',true);return}if(!confirm(`Usunąć „${o.title}” z wersji roboczej?`))return;data[view].splice(selected,1);selected=Math.max(0,selected-1);changed();drawView()};for(const [id,dir]of [['move-up',-1],['move-down',1]])document.querySelector('#'+id).onclick=()=>{const arr=data[view],next=selected+dir;[arr[selected],arr[next]]=[arr[next],arr[selected]];selected=next;changed();drawView()}}
function navigationEditor(){return `<div class="editor-help">Zarządzaj menu i odnośnikami w stopce. Dla podstron podaj adres w formacie /o-nas/. Dla zewnętrznych witryn używaj pełnego adresu https://.</div>${['navigation','footerLinks'].map(k=>`<div class="panel" style="margin-bottom:20px"><div class="form-heading"><h2>${k==='navigation'?'Menu główne':'Odnośniki w stopce'}</h2><button class="btn outline" data-add-link="${k}">+ Dodaj odnośnik</button></div><div class="editor-form" style="margin-top:20px">${data[k].map((l,i)=>`<div class="field-columns" data-link-row="${k}:${i}"><label>Tekst odnośnika<input data-link-field="label" value="${esc(l.label)}"></label><label>Adres<input data-link-field="href" value="${esc(l.href)}"></label><div><button class="btn outline" data-link-move="${k}:${i}" ${i===0?'disabled':''}>↑ Przesuń wyżej</button> <button class="btn outline" data-remove-link="${k}:${i}">Usuń</button></div></div>`).join('')}</div></div>`).join('')}`}
function mediaEditor(){return `<div class="editor-help">Zdjęcia trafiają do repozytorium GitHub. Następnie użyj ich adresu w ustawieniach, artykule lub ogłoszeniu. Dozwolone: JPG, PNG, WEBP do 3 MB. Dodawaj tylko materiały, które możesz opublikować.</div><div class="panel" style="margin-bottom:20px"><h2>Dodaj zdjęcie</h2><input type="file" id="media-upload" accept="image/jpeg,image/png,image/webp"><p>${demo?'W podglądzie zdjęcia są przechowywane lokalnie jako dane demonstracyjne.':'Przesłanie pliku tworzy osobny zapis w GitHubie. Dodanie do biblioteki zatwierdź przyciskiem publikacji.'}</p></div><div class="media-grid">${data.media.map((m,i)=>`<div class="media-card"><img src="${asset(m.url)}" alt="${esc(m.alt)}"><div><p>${esc(m.name)}</p><input value="${esc(m.url)}" readonly aria-label="Adres pliku"><label>Opis alternatywny<input data-alt="${i}" value="${esc(m.alt)}"></label><button class="btn outline" data-copy="${i}">Kopiuj adres</button> <button class="btn outline" data-remove-media="${i}">Usuń z biblioteki</button></div></div>`).join('')}</div>`}
async function bindMedia(){document.querySelectorAll('[data-alt]').forEach(e=>e.oninput=()=>{data.media[Number(e.dataset.alt)].alt=e.value;changed()});document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(data.media[Number(b.dataset.copy)].url);toast('Skopiowano adres')}catch{toast('Zaznacz i skopiuj adres w polu powyżej.')}});document.querySelectorAll('[data-remove-media]').forEach(b=>b.onclick=()=>{if(!confirm('Usunąć odnośnik z biblioteki? Plik w repozytorium pozostanie dostępny dla istniejących artykułów.'))return;data.media.splice(Number(b.dataset.removeMedia),1);changed();drawView()});document.querySelector('#media-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3000000){toast('Wybierz JPG, PNG lub WEBP do 3 MB.',true);return}if(demo){toast('Przesyłanie plików do GitHuba jest dostępne po zalogowaniu. W podglądzie edytuj adresy istniejących zdjęć.');return}e.target.disabled=true;try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const r=await api('media',{method:'POST',body:JSON.stringify({base64,type:file.type})});data.media.push({id:'media-'+Date.now().toString(36),url:r.url,name:file.name,alt:''});changed();drawView();toast('Zdjęcie zapisano. Opublikuj bibliotekę, aby zapamiętać jego opis.')}catch(err){toast(err.message,true);e.target.disabled=false}}}
async function remoteView(k){const el=document.querySelector('#view-content');el.innerHTML='<div class="panel loading-line">Pobieranie danych…</div>';if(demo){el.innerHTML='<div class="panel blank-state"><h2>'+esc(labels[k])+'</h2><p>Ta sekcja pokazuje rzeczywiste dane po zalogowaniu do Cloudflare i połączeniu z GitHubem. Podgląd nie wyświetla fikcyjnych użytkowników ani historii publikacji.</p></div>';return}try{if(k==='history'){const r=await api('history');if(view!==k)return;el.innerHTML=`<div class="panel"><h2>Historia zmian treści</h2><p>Przed przywróceniem starej wersji utwórz kopię aktualnej treści. Wersje i porównania są dostępne w GitHubie.</p><div class="table-wrap"><table class="admin-table"><thead><tr><th>Data</th><th>Zmiana</th><th>Wersja</th></tr></thead><tbody>${r.commits.map(c=>`<tr><td>${esc(new Date(c.date).toLocaleString('pl-PL'))}</td><td>${esc(c.message)}</td><td><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.sha.slice(0,8))} ↗</a></td></tr>`).join('')}</tbody></table></div></div>`}else if(k==='team'){if(session.role!=='admin'){el.innerHTML='<div class="panel">Zarządzanie redakcją jest dostępne administratorowi.</div>';return}const r=await api('team');if(view!==k)return;el.innerHTML=`<div class="panel"><h2>Redakcja i uprawnienia</h2><p>Administrator zarządza treścią i redakcją. Redaktor edytuje treść. Każdy adres musi być również dopuszczony przez politykę logowania Cloudflare Access. Ta operacja nie wysyła zaproszeń.</p><form class="team-form" id="team-form"><input name="email" type="email" required placeholder="Adres e-mail"><select name="role"><option value="editor">Redaktor</option><option value="admin">Administrator</option></select><button class="btn">Dodaj / zmień rolę</button></form><table class="admin-table"><tbody>${r.owners.map(e=>`<tr><td>${esc(e)}</td><td>Właściciel (Cloudflare)</td><td></td></tr>`).join('')}${r.team.map(m=>`<tr><td>${esc(m.email)}</td><td>${m.role==='admin'?'Administrator':'Redaktor'}</td><td><button class="btn outline" data-remove-user="${esc(m.email)}">Odbierz dostęp</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelector('#team-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));await api('team',{method:'PUT',body:JSON.stringify(d)});toast('Zapisano rolę. Sprawdź też politykę Cloudflare Access.');remoteView(k)}catch(err){toast(err.message,true)}};document.querySelectorAll('[data-remove-user]').forEach(b=>b.onclick=async()=>{if(!confirm('Odebrać dostęp redakcyjny temu kontu?'))return;try{await api('team',{method:'DELETE',body:JSON.stringify({email:b.dataset.removeUser})});remoteView(k)}catch(e){toast(e.message,true)}})} }catch(e){if(view===k)el.innerHTML=`<div class="panel blank-state"><h2>Nie udało się pobrać danych</h2><p>${esc(e.message)}</p></div>`}}
function statistics(){const max=Math.max(1,...data.categories.map(c=>data.posts.filter(x=>x.category===c.id).length));return `<div class="dashboard-grid"><div class="panel"><h2>Artykuły według kategorii</h2><p>Rozkład rzeczywistych materiałów w repozytorium.</p><div class="content-bars">${data.categories.map(c=>{const n=data.posts.filter(p=>p.category===c.id).length;return `<div class="content-bar-row"><span>${esc(c.title)}</span><div class="track"><span style="width:${n/max*100}%"></span></div><b>${n}</b></div>`}).join('')}</div></div><div class="panel"><h2>Odwiedziny witryny</h2><p>Pomiar odwiedzin nie został podłączony. Dashboard nie pokazuje szacowanych ani wymyślonych liczb.</p>${data.settings.analyticsUrl?`<a class="btn" href="${esc(data.settings.analyticsUrl)}" target="_blank" rel="noopener">Otwórz statystyki ↗</a>`:'<p>Możesz dodać adres swojego panelu analitycznego w Ustawieniach. Cloudflare Web Analytics wymaga osobnego uruchomienia na Twoim koncie.</p>'}<h2 style="margin-top:30px">Publikacje GitHub Pages</h2><button class="btn outline" id="load-deployments">Sprawdź ostatnie publikacje</button><div id="deployment-results"></div></div></div>`}
function drawView(){const el=document.querySelector('#view-content');if(['team','history'].includes(view)){remoteView(view);return}if(view==='dashboard'){el.innerHTML=dashboard();bindGo()}else if(view==='home'){el.innerHTML=homeEditor();bindForm(data.home)}else if(view==='settings'){el.innerHTML=settingsEditor();bindForm(data.settings,{regionOptions:v=>v.split('\n').map(x=>x.trim()).filter(Boolean)});document.querySelector('#import-content').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1500000)throw Error('Kopia jest za duża');const d=JSON.parse(await f.text()),errors=validateContent(d);if(errors.length)throw Error(errors.join('\n'));if(!confirm('Zastąpić bieżącą wersję roboczą zawartością kopii?'))return;data=d;changed();shell();toast('Wczytano kopię roboczą. Sprawdź podgląd przed publikacją.')}catch(err){toast(err.message,true)}}}else if(templates[view]){el.innerHTML=collectionEditor();bindCollection()}else if(view==='navigation'){el.innerHTML=navigationEditor();document.querySelectorAll('[data-link-field]').forEach(i=>i.oninput=()=>{const [k,n]=i.closest('[data-link-row]').dataset.linkRow.split(':');data[k][Number(n)][i.dataset.linkField]=i.value;changed()});document.querySelectorAll('[data-add-link]').forEach(b=>b.onclick=()=>{data[b.dataset.addLink].push({label:'Nowy odnośnik',href:'/'});changed();drawView()});document.querySelectorAll('[data-remove-link]').forEach(b=>b.onclick=()=>{const[k,n]=b.dataset.removeLink.split(':');data[k].splice(Number(n),1);changed();drawView()});document.querySelectorAll('[data-link-move]').forEach(b=>b.onclick=()=>{const[k,v]=b.dataset.linkMove.split(':'),n=Number(v);[data[k][n-1],data[k][n]]=[data[k][n],data[k][n-1]];changed();drawView()})}else if(view==='media'){el.innerHTML=mediaEditor();bindMedia()}else if(view==='stats'){el.innerHTML=statistics();document.querySelector('#load-deployments').onclick=async()=>{const r=document.querySelector('#deployment-results');if(demo){r.innerHTML='<p>Historia wdrożeń jest dostępna po zalogowaniu.</p>';return}try{const d=await api('deployments');r.innerHTML=d.runs.map(w=>`<p><a href="${esc(w.url)}" target="_blank" rel="noopener">${esc(w.conclusion||w.status)} · ${esc(w.commit.slice(0,8))} ↗</a></p>`).join('')||'<p>Brak uruchomień workflow. Włącz GitHub Actions w ustawieniach Pages.</p>'}catch(e){r.textContent=e.message}}}}
async function start(){let publicData;try{publicData=await fetch('/content/public.json').then(r=>r.json());if(demo){data=publicData;session={email:'Podgląd redakcji',role:'admin',repo:'mostpomocy/mostpomocy.github.io',branch:'demo'}}else{try{session=await api('session');const r=await api('content');data=r.content;sha=r.sha}catch(e){root.innerHTML=`<div class="login-shell"><a class="brand" href="/"><img src="/assets/logo.svg" width="48" alt=""><span><strong>MostPomocy.pl</strong><small>Panel redakcyjny</small></span></a><h1>Twoja witryna.<br>Wszystko pod kontrolą.</h1><p>Edytuj treści, zdjęcia, artykuły i ogłoszenia. Zmiany zapisują się w GitHubie, a stronę publikuje GitHub Pages.</p>${publicData.settings.adminUrl?`<a class="btn" href="${esc(publicData.settings.adminUrl)}">Zaloguj przez Cloudflare ${icon('arrow')}</a>`:'<p class="notice">Logowanie Cloudflare nie jest jeszcze skonfigurowane. Kod panelu jest gotowy, ale wymaga uruchomienia Workera i polityki Access na koncie właściciela.</p>'}<a class="btn outline" href="/admin/?demo=1">Otwórz podgląd dashboardu</a><p class="notice">Podgląd pozwala wypróbować edycję. Nie daje dostępu do zapisu w GitHubie.</p><a href="/" class="back-home">← Wróć do witryny</a></div>`;return}}try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&saved.demo===demo&&saved.repo===session.repo&&saved.branch===session.branch){const valid=validateContent(saved.data).length===0;if(valid&&confirm('Znaleziono lokalną kopię roboczą. Przywrócić ją?')){data=saved.data;sha=saved.sha||sha;dirty=true}}}catch{}shell()}catch(e){root.innerHTML=`<div class="login-shell"><h1>Nie udało się uruchomić panelu</h1><p>${esc(e.message)}</p><a class="btn" href="/admin/">Spróbuj ponownie</a><a class="back-home" href="/">Wróć do strony</a></div>`}}
start();
